const entrada = $input.all();
const saida = [];

for (const item of entrada) {
  const clientes = item.json.body?.clientes ?? item.json.clientes ?? [];

  for (const cliente of clientes) {
    let mensagem;

    switch ((cliente.perfil || "").toLowerCase()) {
      case "conservador":
        mensagem = `Olá, ${cliente.nome}! Vamos explorar opções que priorizem estabilidade e preservação do capital.`;
        break;

      case "moderado":
        mensagem = `Olá, ${cliente.nome}! Vamos explorar alternativas diversificadas, considerando seu perfil e seus objetivos.`;
        break;

      case "arrojado":
        mensagem = `Olá, ${cliente.nome}! Vamos estudar alternativas com maior exposição à renda variável e seus respectivos riscos.`;
        break;

      default:
        mensagem = `Olá, ${cliente.nome}! Vamos conhecer seus objetivos para avaliar alternativas adequadas ao seu perfil.`;
    }

    saida.push({
      json: {
        ...cliente,
        mensagem
      }
    });
  }
}

return saida;

const texto = $input.first().json.data;

const linhas = texto
  .replace(/\\n/g, "\n")
  .trim()
  .split(/\r?\n/)
  .filter(linha => linha.trim() !== "");

const cabecalhos = linhas[0].split(",").map(c => c.trim());

return linhas.slice(1).map(linha => {
  const valores = linha.split(",");
  const registro = {};

  cabecalhos.forEach((coluna, i) => {
    registro[coluna] = (valores[i] || "").trim();
  });

  return { json: registro };
});

const clientes = $("Code in JavaScript").all().map(item => item.json);
const investimentos = $("Code in JavaScript1").all().map(item => item.json);

function converterSaldo(valor) {
  if (typeof valor === "number") return valor;

  return Number(
    String(valor ?? "")
      .replace(/R\$/g, "")
      .replace(/\s/g, "")
      .replace(/\./g, "")
      .replace(",", ".")
  ) || 0;
}

const resultado = [];

for (const cliente of clientes) {
  const saldo = converterSaldo(cliente.saldo);
  const perfil = String(cliente.perfil ?? "")
    .trim()
    .toLowerCase();

  const opcoes = investimentos.filter(inv => {
    const mesmoPerfil =
      String(inv.perfil ?? "").trim().toLowerCase() === perfil;

    return mesmoPerfil && saldo >= converterSaldo(inv.minimo);
  });

  const listaProdutos = opcoes
    .map(opcao =>
      `- ${opcao.produto} | Mínimo: R$ ${opcao.minimo} | Rentabilidade: ${opcao.rentabilidade}`
    )
    .join("\n");

  const mensagemFinal = opcoes.length > 0
    ? `${cliente.mensagem}\n\nOpções para conhecer:\n${listaProdutos}\n\nConsulte os riscos, custos e condições de cada produto antes de decidir.`
    : `${cliente.mensagem}\n\nNão encontramos opções que atendam ao saldo informado na base atual.`;

  resultado.push({
    json: {
      ...cliente,
      saldoNumerico: saldo,
      investimentosElegiveis: opcoes,
      quantidadeOpcoes: opcoes.length,
      mensagemFinal
    }
  });
}

return resultado;
